<?php
declare(strict_types=1);

// Import snapshot JSON generated by tools/parse_xlsx.mjs into MariaDB.
// Run after database/schema.sql has been applied.
$root = dirname(__DIR__);
$sourceDir = $root . DIRECTORY_SEPARATOR . 'exports';
$files = glob($sourceDir . DIRECTORY_SEPARATOR . '*.json') ?: [];
$sheets = [];
foreach ($files as $file) {
    if (basename($file) === 'summary.json' || basename($file) === 'all_sheets.json') continue;
    $data = json_decode((string)file_get_contents($file), true);
    if (is_array($data['title'] ?? null)) continue;
    if (!empty($data['title'])) $sheets[$data['title']] = $data;
}

function numv(mixed $v): float { $s=trim((string)($v??'')); if($s==='')return 0.0; if(str_contains($s,',')&&str_contains($s,'.')){if(strrpos($s,',')>strrpos($s,'.'))$s=str_replace(',','.',str_replace('.','',$s));else$s=str_replace(',','',$s);}elseif(str_contains($s,','))$s=str_replace(',','.',$s);return is_numeric($s)?(float)$s:0.0; }
function boolv(mixed $v): int { return in_array(strtoupper(trim((string)$v)),['TRUE','1','YES','Y','SẴN SÀNG POST'],true)?1:0; }
function datev(mixed $v): ?string { $s=trim((string)($v??''));if($s==='')return null;if(preg_match('/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/',$s,$m))return sprintf('%04d-%02d-%02d',$m[3],$m[2],$m[1]);if(is_numeric($s)&&$s>30000&&$s<70000)return gmdate('Y-m-d',(int)(($s-25569)*86400));$d=date_create($s);return $d?$d->format('Y-m-d'):null; }
function rows(string $title): array { global $sheets; return $sheets[$title]['rows']??[]; }
function val(array $row,int $i): string { return trim((string)($row['values'][$i]??'')); }
function keyv(mixed $v): string { $s=trim((string)($v??'')); if(preg_match('/^[+-]?(?:\d+\.?\d*|\.\d+)[eE][+-]?\d+$/',$s)) return sprintf('%.0f',(float)$s); return $s; }
function insertRows(PDO $db,string $sql,array $rows): void { $st=$db->prepare($sql);foreach($rows as $args){$args=array_map(fn($v)=>is_string($v)?keyv($v):$v,$args);$st->execute($args);} }

$host=getenv('KHO_DB_HOST')?:'127.0.0.1';$port=getenv('KHO_DB_PORT')?:'3306';$name=getenv('KHO_DB_NAME')?:'kho_npl';$user=getenv('KHO_DB_USER')?:'root';$pass=getenv('KHO_DB_PASS')?:'';
$db=new PDO("mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$db->exec('SET FOREIGN_KEY_CHECKS=0');foreach(['audit_logs','error_logs','idempotency_requests','document_sequences','stock_ledger','stock_balances','adjustments','production_returns','issue_lines','issues','receipt_lines','receipts','reservations','purchase_request_lines','active_bbsx','dmsx_lines','products','suppliers','materials','user_roles','app_users','app_config','source_syncs'] as $t)$db->exec("TRUNCATE TABLE `$t`");$db->exec('SET FOREIGN_KEY_CHECKS=1');$db->beginTransaction();

$materialRows=[];foreach(rows('DM_VẬT TƯ') as $r){$materialRows[]=[val($r,0),val($r,1)?:val($r,0),val($r,2)?:'đvt',val($r,3),val($r,4),val($r,5),val($r,6),val($r,7),val($r,8),val($r,9)?:'STOCK',boolv(val($r,10)),datev(val($r,11)),datev(val($r,12))];}insertRows($db,'INSERT INTO materials(material_id,material_name,uom,material_group,material_type,fabric_name,color,specification,fabric_width,item_class,is_active,source_updated_at,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE material_name=VALUES(material_name),uom=VALUES(uom),item_class=VALUES(item_class),is_active=VALUES(is_active)', $materialRows);
$supplierRows=[];foreach(rows('DM_NHÀ CUNG CẤP') as $r){$supplierRows[]=[val($r,0),val($r,1),val($r,2)?:val($r,6)?:val($r,0),val($r,3),val($r,4),val($r,5),val($r,6),val($r,7),val($r,8),val($r,9),val($r,10),val($r,11),val($r,12),boolv(val($r,13))];}insertRows($db,'INSERT INTO suppliers(supplier_id,supplier_short_code,supplier_display_name,legal_name,tax_code,misa_supplier_code,misa_supplier_name,contact_person,phone,bank_account,bank_name,account_holder,supplier_group,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE supplier_display_name=VALUES(supplier_display_name),is_active=VALUES(is_active)',$supplierRows);
$productRows=[];foreach(rows('DM_ĐƠN HÀNG SẢN PHẨM') as $r){$productRows[]=[val($r,4),val($r,0),val($r,1),val($r,2),val($r,3),val($r,5),val($r,6),val($r,7),numv(val($r,8)),val($r,9),val($r,10),val($r,11),val($r,14),val($r,17),datev(val($r,16))];}insertRows($db,'INSERT INTO products(product_code,contract_code,order_code,execution_code,execution_type,product_type_code,product_name,gender,production_qty,customer_id,customer_name,order_name,source_status,source_row_key,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE product_name=VALUES(product_name),production_qty=VALUES(production_qty),execution_code=VALUES(execution_code)', $productRows);
$dmsxRows=[];foreach(rows('DM_ĐỊNH MỨC SX') as $r){if(!val($r,2)||!val($r,4)||!val($r,7))continue;$dmsxRows[]=[val($r,0),val($r,1),val($r,2),val($r,3),val($r,4),val($r,5),numv(val($r,6)),val($r,7),val($r,8),val($r,9),val($r,10),val($r,11),numv(val($r,12)),numv(val($r,13)),numv(val($r,14)),numv(val($r,15)),numv(val($r,16)),val($r,17),val($r,18),val($r,19),val($r,20),val($r,24),val($r,25),val($r,28),datev(val($r,27))];}insertRows($db,'INSERT INTO dmsx_lines(dmsx_date,pr_code,execution_code,order_name,product_code,product_name,production_qty,material_id,material_name,uom,material_type,fabric_width,bom_qty,waste_rate,gross_requirement_qty,estimated_unit_price,estimated_amount,supplier_display,supplier_id,required_fabric_date,required_trim_date,status_legacy,order_code,source_row_key,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$dmsxRows);
$prRows=[];foreach(rows('DM_ĐNMH ĐANG MỞ') as $r){if(!val($r,0)||!val($r,8))continue;$prRows[]=[val($r,0),val($r,1),datev(val($r,2)),val($r,3),val($r,4),val($r,5),val($r,6),val($r,7),val($r,8),val($r,9),val($r,10),numv(val($r,11)),numv(val($r,12)),numv(val($r,13)),numv(val($r,14)),numv(val($r,15)),numv(val($r,16)),numv(val($r,17)),numv(val($r,18)),datev(val($r,19)),val($r,20),boolv(val($r,24)),val($r,23),datev(val($r,22))];}insertRows($db,'INSERT INTO purchase_request_lines(pr_ref_key,pr_code,pr_date,supplier_id,supplier_name,order_code,execution_code,product_code,material_id,material_name,uom,gross_requirement_qty,reserved_stock_qty,net_requirement_qty,ordered_qty,estimated_unit_price,estimated_amount,received_qty,remaining_qty,required_date,line_status,operational_active_flag,source_row_key,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE remaining_qty=VALUES(remaining_qty),received_qty=VALUES(received_qty),operational_active_flag=VALUES(operational_active_flag)',$prRows);
$bbsxRows=[];foreach(rows('DM_BBSX ĐANG HOẠT ĐỘNG') as $r){if(!val($r,0)||!val($r,1))continue;$status=val($r,3);$tracked=in_array(strtoupper(preg_replace('/\s+/',' ',$status)),['ĐANG MUA NPL','ĐÃ ĐỒNG BỘ NPL','ĐỢI CHỐT VẢI','ĐANG MUA FOB','ĐANG TÁI CHẾ'],true)?1:0;$bbsxRows[]=[val($r,0),val($r,1),val($r,2),$status,datev(val($r,4)),$tracked];}insertRows($db,'INSERT INTO active_bbsx(execution_code,product_code,source_name,source_status,synced_at,is_npl_tracking) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE source_status=VALUES(source_status),is_npl_tracking=VALUES(is_npl_tracking)',$bbsxRows);
$configRows=[];foreach(rows('HT_CẤU HÌNH') as $r){if(val($r,0))$configRows[]=[val($r,0),val($r,1),val($r,2),val($r,3),val($r,5)?:'ACTIVE'];}insertRows($db,'INSERT INTO app_config(config_key,config_value,data_type,description,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status=VALUES(status)',$configRows);
$permRows=[];foreach(rows('HT_PHÂN QUYỀN') as $r){if(!val($r,0)||!val($r,1))continue;$email=strtolower(val($r,0));$db->prepare('INSERT IGNORE INTO app_users(email,display_name) VALUES(?,?)')->execute([$email,$email]);$permRows[]=[ $email,val($r,1),boolv(val($r,2)),datev(val($r,3)),datev(val($r,4)),val($r,5) ];}insertRows($db,'INSERT INTO user_roles(email,role_code,is_active,effective_from,effective_to,note) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE is_active=VALUES(is_active),effective_from=VALUES(effective_from),effective_to=VALUES(effective_to),note=VALUES(note)',$permRows);
$srcRows=[];foreach(rows('HT_NGUỒN DỮ LIỆU') as $r){if(val($r,0))$srcRows[]=[val($r,0),val($r,1),val($r,2),val($r,3),val($r,4),val($r,5),val($r,6),val($r,7),datev(val($r,8)),val($r,9)];}insertRows($db,'INSERT INTO source_syncs(source_code,file_title,file_id,sheet_name,target_ref,mode,sync_method,notes,last_sync_at,sync_status) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sync_status=VALUES(sync_status),last_sync_at=VALUES(last_sync_at),notes=VALUES(notes)',$srcRows);
$ledgerRows=[];foreach(rows('SỔ_KHO') as $r){if(!val($r,0)||!val($r,7))continue;$ledgerRows[]=[val($r,0),datev(val($r,1))?datev(val($r,1)).' 12:00:00':date('Y-m-d H:i:s'),datev(val($r,2))?:date('Y-m-d'),val($r,3),val($r,4),val($r,5),val($r,6),val($r,7),numv(val($r,8)),numv(val($r,9)),numv(val($r,10)),numv(val($r,11)),numv(val($r,12)),numv(val($r,13)),numv(val($r,14)),numv(val($r,15)),val($r,16),val($r,17),val($r,18),val($r,19),val($r,20),val($r,21)?:'IMPORT',val($r,22)?:'THU_NGHIEM',val($r,23)?:'IMPORT-'.$r['row']];}insertRows($db,'INSERT IGNORE INTO stock_ledger(ledger_id,posted_at,transaction_date,transaction_type,transaction_id,transaction_line_id,document_code,material_id,qty_in,qty_out,unit_cost,amount_in,amount_out,running_qty,running_value,avg_cost_after,order_code,execution_code,product_code,supplier_id,pr_code,created_by,source_environment,source_client_request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$ledgerRows);
$db->exec('INSERT INTO stock_balances(material_id,physical_qty,stock_value,avg_cost) SELECT material_id,SUM(qty_in-qty_out),SUM(amount_in-amount_out),CASE WHEN SUM(qty_in-qty_out)=0 THEN 0 ELSE SUM(amount_in-amount_out)/SUM(qty_in-qty_out) END FROM stock_ledger GROUP BY material_id ON DUPLICATE KEY UPDATE physical_qty=VALUES(physical_qty),stock_value=VALUES(stock_value),avg_cost=VALUES(avg_cost)');
$db->commit();echo json_encode(['ok'=>true,'materials'=>count($materialRows),'suppliers'=>count($supplierRows),'products'=>count($productRows),'dmsx'=>count($dmsxRows),'purchaseRequestLines'=>count($prRows),'activeBbsx'=>count($bbsxRows),'ledger'=>count($ledgerRows)],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),PHP_EOL;
